// Input now includes both: text from Extract node AND meta from Drive trigger
const item = items[0];

// Extract text from common keys produced by the PDF node
let text = item.json?.text || item.json?.data || item.json?.content || '';
if (Array.isArray(text)) text = text.join('\n');

// Defensive binary fallback (rare)
if (!text && item.binary?.data?.data) {
  text = Buffer.from(item.binary.data.data, item.binary.data.encoding || 'base64').toString('utf8');
}

// Metadata is present directly on the merged item from the Drive trigger
const source_file_id = item.json.id || null;
const source_file_name = item.json.name || item.json.fileName || null;
let source_file_url = item.json.webViewLink || null;

// Synthesize a link if only id is present
if (!source_file_url && source_file_id) {
  source_file_url = `$('Drive Download').first().json.webViewLink`;
}

if (!text || !text.trim()) {
  throw new Error(`Empty text extracted from PDF. File: ${source_file_name || 'Unknown'}`);
}

return [
  {
    json: {
      extracted_text: text,
      source_file_id,
      source_file_name,
      source_file_url,
    },
  },
];

// 1) Get the raw OpenAI text from multiple possible locations (incl. $json.output)
let raw =
  items[0]?.json?.output ??
  items[0]?.json?.text ??
  items[0]?.json?.content ??
  items[0]?.json?.response ??
  items[0]?.json?.choices?.[0]?.message?.content ??
  (typeof items[0]?.json === 'string' ? items[0].json : null);

if (!raw) {
  throw new Error('Missing OpenAI response');
}

// If the node upstream already returned an object, accept it
if (typeof raw === 'object') {
  raw = JSON.stringify(raw);
}

// 2) Clean up common wrappers like ```json ... ``` or leading "json\n"
function cleanRaw(s) {
  let t = String(s).trim();
  // remove code fences
  t = t.replace(/```json/gi, '```').replace(/```/g, '').trim();
  // drop a leading "json" language hint on its own line
  t = t.replace(/^json\s*/i, '').trim();
  return t;
}
raw = cleanRaw(raw);

// 3) Parse strictly; if it fails, salvage the first {...} block
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('OpenAI returned non-JSON');
  parsed = JSON.parse(m[0]);
}

// 4) Normalize fields
function isoOrNull(v){
  if (v === null || v === undefined || v === '') return null;
  const d = new Date(String(v).trim());
  if (Number.isNaN(d.getTime())) return null;
  return d.toISOString().slice(0,10);
}
function numOrNull(v){
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/,/g, ''));
  return Number.isNaN(n) ? null : n;
}

// Coerce/trim basics
parsed.invoice_number   = (parsed.invoice_number ?? '').toString().trim();
parsed.vendor_name      = (parsed.vendor_name ?? '').toString().trim();
parsed.invoice_date     = isoOrNull(parsed.invoice_date);
parsed.due_date         = isoOrNull(parsed.due_date);
parsed.total_amount     = numOrNull(parsed.total_amount);
parsed.currency         = (parsed.currency ?? '').toString().trim().toUpperCase() || null;
parsed.notes            = (parsed.notes === null || parsed.notes === undefined || String(parsed.notes).trim()==='') ? null : String(parsed.notes).trim();
parsed.source_file_id   = (parsed.source_file_id ?? '').toString().trim();
parsed.source_file_name = (parsed.source_file_name ?? '').toString().trim();
parsed.source_file_url  = (parsed.source_file_url ?? '').toString().trim();

// Normalize line items
if (!Array.isArray(parsed.line_items)) parsed.line_items = [];
parsed.line_items = parsed.line_items.map(li => {
  const description = (li?.description ?? '').toString();
  const qty         = numOrNull(li?.qty) ?? 0;
  const unit_price  = numOrNull(li?.unit_price) ?? 0;
  const line_total  = numOrNull(li?.line_total) ?? (qty * unit_price);
  return { description, qty, unit_price, line_total };
});

// 5) Required fields
const required = [
  'invoice_number',
  'invoice_date',
  'vendor',
  'total_amount',
  'currency',
  'source_file_id',
  'source_file_name',
  'source_file_url',
];
for (const k of required) {
  if (parsed[k] === null || parsed[k] === undefined || parsed[k] === '') {
    throw new Error(`Missing required field: ${k}`);
  }
}

return [{ json: parsed }];
